#' Convert eCH-0157 XML file into a dataframe
#'
#' @description
#'`parse_eCH_0157()` turns an eCH-0157 XML file for an election day into a dataframe.
#' Currently, the function supports input files for votes generated by the application VOTING.
#'
#' @param file Path to your XML file.
#'
#' @return A dataframe.
#' @export
#'
#' @examples
#' filepath <- system.file(
#'   "extdata",
#'   "eCH-0157_abraxas_elections_ZH_majority_2026-06-16.xml",
#'   package = "eCHparser"
#' )
#'
#' votedata <- parse_eCH_0157(filepath)
parse_eCH_0157 <- function(file){

  # Load file and strip namespaces
  xml_data <- xml2::read_xml(file)

  # Strip namespaces
  xml_data_stripped <- strip_namespaces(xml_data)

  # Load initial delivery part of the file
  node_initialDelivery <- xml2::xml_find_first(xml_data_stripped, ".//initialDelivery")


  # SPECIFY SPECIAL NODES' NAMES ===============================================


  # Define all nodes whose parents' names need to be specified
  nodes_to_specify <- c("language", "idName", "elementName", "electionRelation")

  # Apply the node specification fucntion to these nodes
  lapply(nodes_to_specify, function(nodename){
    specify_node(node_initialDelivery, nodename)
  })


  # TURN TO DF =================================================================


  ## Contest Information -------------------------------------------------------


  # Get structure of the indexed node as a list
  initialDelivery_list <- node_initialDelivery |>
    xml2::as_list()

  # Number the names to create a unique name for each child
  names(initialDelivery_list) <- paste0(1:length(initialDelivery_list),"_", names(initialDelivery_list))

  # Define contest node and electionGroupBallot nodes as named lists
  contest_list <- initialDelivery_list[1]
  electionGroupBallot_list <- initialDelivery_list[-1]

  # Unlist the list
  contest_unlist <- unlist(contest_list)

  # List to df and add unique id (if )
  contest_df_long <- to_df(contest_unlist, names(contest_unlist)) |>
    dplyr::mutate(unique_id = gsub("^(\\d+)_.*", "\\1", var))

  # Write contest information to a df (and add a join_id)
  contest_df <- contest_df_long |>
    to_wide() |>
    dplyr::select(-unique_id) |>
    tidyr::unnest_longer(
      tidyselect::everything(),
      keep_empty = TRUE
    ) |>
    dplyr::mutate(join_id = 1879)


  ## Election Information ------------------------------------------------------


  # Define all electionGroupBallot nodes.
  # This is needed to work with further down the tree.
  # For the next level, we already defined a named list above.
  electionGroupBallot_nodes <- xml2::xml_find_all(node_initialDelivery, ".//electionGroupBallot")

  # Parse through all electionGroupBallot nodes
  electionGroup_list <- lapply(seq_along(electionGroupBallot_nodes), function(electionGroupBallot_index){


    ### Parse Election Group Ballot Information --------------------------------


    electionGroupBallot <- electionGroupBallot_list[electionGroupBallot_index]

#     # Define the doi of the supperior authority of the election group (domainOfInfluenceIdentification)
#     domainOfInfluenceIdentification_df <- data.frame(electionGroupBallot_domainOfInfluenceIdentification = xml2::xml_text(xml2::xml_find_first(
#       electionGroupBallot_nodes[electionGroupBallot_index],
#       "domainOfInfluenceIdentification"
#     )))

    # Define nodes of interest as named list
    electionGroupInfo_list <- list(electionGroupBallot[[1]][names(electionGroupBallot[[1]]) != "electionInformation"])
    names(electionGroupInfo_list) <- names(electionGroupBallot)

    # Unlist
    electionGroupInfo_unlist <- unlist(electionGroupInfo_list)

    # To df and add unique ID
    electionGroupInfo_df_long <- to_df(electionGroupInfo_unlist, names(electionGroupInfo_unlist)) |>
      dplyr::mutate(unique_id = gsub("^(\\d+)_.*", "\\1", var))

    # Write electionGroupBallot information to a df and add ID for join
    electionGroupInfo_df <- electionGroupInfo_df_long |>
      to_wide() |>
      dplyr::select(-unique_id) |>
      tidyr::unnest_longer(
        tidyselect::everything(),
        keep_empty = TRUE
      ) |>
      dplyr::mutate(
        electionGroupBallot_index = as.character(electionGroupBallot_index), # Add an election group ballot id
        join_id = 1879 # Add join id
      )


    ### Parse Election Information ---------------------------------------------


    # Define all electionInformation nodes
    electionInformation_nodes <- xml2::xml_find_all(electionGroupBallot_nodes[electionGroupBallot_index], ".//electionInformation")

    # Parse through all electionInformation nodes
    electionInformation_list <- lapply(seq_along(electionInformation_nodes), function(electionInformation_index) {

      # Define node of interest
      electionInfo <- electionInformation_nodes[[electionInformation_index]]

      # Get structure of the indexed node as a list
      electionInfo_list <- electionInfo |>
        xml2::as_list()

      # Handle duplicated elements in the election information (i. e. type 2 referenced elections like multiple by-elections)
      if (any(duplicated(electionInfo_list[[1]] |> names()))) {

        # Identify recurring element names and their occurrences
        element_names <- names(electionInfo_list[[1]])
        unique_names <- unique(element_names)
        recurring_names <- element_names[duplicated(element_names)]

        # Combine recurring elements
        for (name in recurring_names) {

          # Get all occurrences of the recurring element
          elements <- electionInfo_list[[1]][element_names == name]

          # Combine contents into a comma-separated string
          combined_content <- paste(unlist(elements), collapse = ", ") # unlist to handle potential list within lists

          # Replace all occurrences with the combined content
          electionInfo_list[[1]][[name]][[1]][[1]] <- combined_content

        }

        # Keep only unique elements
        electionInfo_list[[1]] <- electionInfo_list[[1]][!duplicated(element_names)]

      }

      # Number the names to create unique names
      names(electionInfo_list) <- paste0(1:length(electionInfo_list),"_", names(electionInfo_list))

      # Unlist the list
      electionInfo_unlist <- unlist(electionInfo_list)

      # List to df and add unique id
      electionInfo_df_long <- to_df(electionInfo_unlist, names(electionInfo_unlist)) |>
        dplyr::mutate(unique_id = gsub("^(\\d+)_.*", "\\1", var))


      #### Election ------------------------------------------------------------


      # Define election information
      election_df <- electionInfo_df_long |>
        dplyr::filter(grepl("election\\.", var)) |>
        to_wide() |>
        dplyr::select(-unique_id) |>
        tidyr::unnest_longer(
          tidyselect::everything(),
          keep_empty = TRUE
        ) |>
        dplyr::mutate(join_id = 1879)


      #### Candidates ----------------------------------------------------------


      # Define candidate information
      candidate_df <- electionInfo_df_long |>
        dplyr::filter(grepl("candidate\\.", var)) |>
        to_wide() |>
        dplyr::select(-unique_id) |>
        tidyr::unnest_longer(
          tidyselect::everything(),
          keep_empty = TRUE
        ) |>
        dplyr::mutate(join_id = 1879)


      #### Lists ---------------------------------------------------------------


      # Check, if there is list information in the data (only the case for proportional elections)
      if (any(grepl("list\\.", electionInfo_df_long$var))) {

        # Define list information
        list_df <- electionInfo_df_long |>
          dplyr::filter(grepl("list\\.", var)) |>
          to_wide() |>
          dplyr::select(-unique_id) |>
          tidyr::unnest_longer(
            tidyselect::everything(),
            keep_empty = TRUE
          ) |>
          dplyr::filter(!is.na(candidatePosition_candidateIdentification)) |>
          dplyr::mutate(candidate_candidateIdentification = candidatePosition_candidateIdentification)

      }


      #### Join ----------------------------------------------------------------


      electionInfo_df <- election_df |>
        dplyr::left_join(candidate_df, by = "join_id")

      if (exists("list_df")) {

        electionInfo_df1 <- electionInfo_df |>
          dplyr::left_join(list_df, by = "candidate_candidateIdentification")

      }

    })

    # Bind rows to df and join them to the election group information df
    electionInformation_df <- electionGroupInfo_df |>
      dplyr::left_join(dplyr::bind_rows(electionInformation_list))

    # Relocate the referenced election columns if they exist
    if (any(grep("referencedElection", names(electionInformation_df)))) {

      # Identify columns containing "referencedElection"
      ref_election_cols <- grep("referencedElection", names(electionInformation_df))

      # Find the index of the column after which we want the referencedElection columns
      identification_index <- which(names(electionInformation_df) == "election_numberOfMandates")

      # If "electionIdentification" doesn't exist, handle the error
      if (length(identification_index) == 0) {
        stop("Column 'election_numberOfMandates' cannot be found in the data frame.")
      }

      # Create the new column order
      new_order <- c(1:identification_index, ref_election_cols, (setdiff(1:ncol(electionInformation_df), c(1:identification_index, ref_election_cols))))

      # Reorder the columns
      electionInformation_df <- electionInformation_df[, new_order]

    }

    return(electionInformation_df)

  })

  # Bind the tables in the electionGroup_list
  electionGroup_df <- dplyr::bind_rows(electionGroup_list)

  # Join contest information and electionGroup data and remove the join_id
  contest_data_complete <- contest_df |>
    dplyr::left_join(electionGroup_df) |>
    dplyr::select(-join_id)

  return(contest_data_complete)

}
